/* test/v34/v34engmap.h - T06 / RS1: the i386 IMAGE -> native offset maps of the V.90 / V.92 engine objects of src/v34/v34_engine_views.h (the chain nodes of the tier 10a arena).
 * Hand-written (seven tiny prefixes; the maps of the big classes are generated by tools/tier_rewrite.py mapheader).  Same format as test/v34/v34objmap.h:
 * {i386 offset, native offset, i386 size, native size, is-pointer}; every byte of [0, size32) is covered.
 * RS1 / M3: the prefixes are now the real classes' leading members (src/v34/v34_engine_views.h).  A pointer member the tier 10a functions FOLLOW (b2s_, mapper_ / tx_,
 * ce_) is a pointer entry (decoded / encoded by v34_img.h); a pointer member they never read is mapped as 4 opaque bytes into the low half of its native
 * 8-byte slot (what the T06 `unk00_` byte regions did for the same bytes).  The V.90 rate chain ends in V90Mapper (w0_ at x86-64 +8), the V.92 one in
 * V92Transmitter (w0_ at +4): two classes, erc90 / erc92 (one `erc` before). */
#ifndef V34ENGMAP_H
#define V34ENGMAP_H

#include "../src/v34/v34_engine_views.h"

#ifndef V34MAPENT_DEFINED
#define V34MAPENT_DEFINED
typedef struct { uint32_t o32, o64, s32, s64; uint8_t isptr; } V34MapEnt;
#endif

#define V34EOPQ(T, m, o32) {(o32), offsetof(T, m), 4, 4, 0}   /* a 4-byte i386 slot, opaque (also an unfollowed pointer: its low half) */

#define V34E90_SIZE32 0x44
#define V34E90_NATSZ sizeof(V90ModulatorPfx)
static const V34MapEnt V34E90_MAP[] = {
  V34EOPQ(V90ModulatorPfx, info_, 0x0), V34EOPQ(V90ModulatorPfx, jd_, 0x4), V34EOPQ(V90ModulatorPfx, v92jd_, 0x8), V34EOPQ(V90ModulatorPfx, dil_, 0xc),
  V34EOPQ(V90ModulatorPfx, mp1_, 0x10), V34EOPQ(V90ModulatorPfx, mp2_, 0x14), V34EOPQ(V90ModulatorPfx, addCp_, 0x18), V34EOPQ(V90ModulatorPfx, mp_, 0x1c),
  V34EOPQ(V90ModulatorPfx, cp_, 0x20), V34EOPQ(V90ModulatorPfx, params_, 0x24),
  V34EOPQ(V90ModulatorPfx, session_, 0x28), V34EOPQ(V90ModulatorPfx, state_, 0x2c), V34EOPQ(V90ModulatorPfx, cnt_, 0x30), V34EOPQ(V90ModulatorPfx, event_, 0x34),
  V34EOPQ(V90ModulatorPfx, p3_, 0x38), V34EOPQ(V90ModulatorPfx, p4_, 0x3c),
  {0x40, offsetof(V90ModulatorPfx, b2s_), 4, sizeof(void *), 1},
};
#define V34E90_NMAP (sizeof V34E90_MAP / sizeof V34E90_MAP[0])

#define V34E92_SIZE32 0x50
#define V34E92_NATSZ sizeof(V92ModulatorPfx)
static const V34MapEnt V34E92_MAP[] = {
  V34EOPQ(V92ModulatorPfx, blk_, 0x0), V34EOPQ(V92ModulatorPfx, half_, 0x4), V34EOPQ(V92ModulatorPfx, cur_, 0x8), V34EOPQ(V92ModulatorPfx, codeA_, 0xc),
  V34EOPQ(V92ModulatorPfx, info_, 0x10), V34EOPQ(V92ModulatorPfx, ja_, 0x14), V34EOPQ(V92ModulatorPfx, dil_, 0x18), V34EOPQ(V92ModulatorPfx, mp_, 0x1c),
  V34EOPQ(V92ModulatorPfx, cp_, 0x20), V34EOPQ(V92ModulatorPfx, skew_, 0x24), V34EOPQ(V92ModulatorPfx, ppm_, 0x28), V34EOPQ(V92ModulatorPfx, state_, 0x2c),
  V34EOPQ(V92ModulatorPfx, cnt_, 0x30), V34EOPQ(V92ModulatorPfx, event_, 0x34), V34EOPQ(V92ModulatorPfx, split_, 0x38), V34EOPQ(V92ModulatorPfx, splitAt_, 0x3c),
  V34EOPQ(V92ModulatorPfx, params_, 0x40), V34EOPQ(V92ModulatorPfx, p3_, 0x44), V34EOPQ(V92ModulatorPfx, p4_, 0x48),
  {0x4c, offsetof(V92ModulatorPfx, b2s_), 4, sizeof(void *), 1},
};
#define V34E92_NMAP (sizeof V34E92_MAP / sizeof V34E92_MAP[0])

/* V90BitsToSymbol / V92BitsToSymbol: one pointer at +0 in both (V92BitsToSymbolPfx has the same layout as V90BitsToSymbolPfx) */
#define V34ERS_SIZE32 0x4
#define V34ERS_NATSZ sizeof(V90BitsToSymbolPfx)
static const V34MapEnt V34ERS_MAP[] = {
  {0x0, offsetof(V90BitsToSymbolPfx, mapper_), 4, sizeof(void *), 1},
};
#define V34ERS_NMAP (sizeof V34ERS_MAP / sizeof V34ERS_MAP[0])

#define V34ERC90_SIZE32 0x8
#define V34ERC90_NATSZ sizeof(V90MapperPfx)
static const V34MapEnt V34ERC90_MAP[] = {
  V34EOPQ(V90MapperPfx, params_, 0x0), V34EOPQ(V90MapperPfx, w0_, 0x4),
};
#define V34ERC90_NMAP (sizeof V34ERC90_MAP / sizeof V34ERC90_MAP[0])

#define V34ERC92_SIZE32 0x8
#define V34ERC92_NATSZ sizeof(V92TransmitterPfx)
static const V34MapEnt V34ERC92_MAP[] = {
  V34EOPQ(V92TransmitterPfx, unk0_, 0x0), V34EOPQ(V92TransmitterPfx, w0_, 0x4),
};
#define V34ERC92_NMAP (sizeof V34ERC92_MAP / sizeof V34ERC92_MAP[0])

#define V34EDM_SIZE32 0x210
#define V34EDM_NATSZ sizeof(V90DemodulatorPfx)
static const V34MapEnt V34EDM_MAP[] = {
  {0x0, offsetof(V90DemodulatorPfx, unk00_), 0x20c, 0x20c, 0},   /* x86-64: the first 0x20c of the 0x2a8 gap bytes */
  {0x20c, offsetof(V90DemodulatorPfx, ce_), 4, sizeof(void *), 1},
};
#define V34EDM_NMAP (sizeof V34EDM_MAP / sizeof V34EDM_MAP[0])

#define V34EMG_SIZE32 0x90
#define V34EMG_NATSZ sizeof(V90ConnectionEvaluatorPfx)
static const V34MapEnt V34EMG_MAP[] = {
  V34EOPQ(V90ConnectionEvaluatorPfx, params_, 0x0),
  {0x4, offsetof(V90ConnectionEvaluatorPfx, w04_), 0x88, 0x88, 0},
  V34EOPQ(V90ConnectionEvaluatorPfx, externalCommand_, 0x8c),
};
#define V34EMG_NMAP (sizeof V34EMG_MAP / sizeof V34EMG_MAP[0])

#endif /* V34ENGMAP_H */
